    formula: 'a = \\operatorname{ReLU}(w_1x_1 + w_2x_2 + b)', formulaExplanation: 'The inputs x₁ and x₂ are scaled by weights w₁ and w₂, shifted by bias b, and passed through ReLU: max(0, z).',
