export type CourseModule = {
  id: string
  number: string
  shortTitle: string
  title: string
  level: 'Beginner' | 'Intermediate' | 'Advanced'
  estimatedHours: string
  lessonCount: number
  lessonSlugs: string[]
  description: string
  outcomes: string[]
}

export function lessonSearchText(lesson: Lesson) {
  return [
    lesson.title,
    lesson.description,
    lesson.module,
    lesson.intro,
    lesson.analogy,
    lesson.formula,
    lesson.formulaExplanation,
    lesson.code,
    lesson.codeExplanation,
    ...lesson.objectives,
    ...lesson.sections.flatMap((section) => [section.title, section.kicker, section.body, section.example ?? '', ...(section.points ?? [])]),
    ...lesson.practice.flatMap((item) => [item.prompt, item.answer, item.solution ?? '']),
    lesson.quiz.question,
    ...lesson.quiz.options,
    lesson.quiz.explanation,
    ...lesson.takeaways,
    lesson.interview.question,
    lesson.interview.answer,
    ...(lesson.miniProject ? [lesson.miniProject.title, lesson.miniProject.objective, ...lesson.miniProject.tasks, lesson.miniProject.extension] : []),
  ].join(' ').toLowerCase()
}

